// его компании.
// Ref: #/components/schemas/Profile
type Profile struct {
	ID        UUID                  `json:"id"`
	CompanyId UUID                  `json:"companyId"`
	Slug      Slug                  `json:"slug"`
	Status    ProfileStatus         `json:"status"`
	FullName  OptNilString          `json:"fullName"`
	Avatar    OptNilAvatar          `json:"avatar"`
	Position  OptNilProfilePosition `json:"position"`
	// Уже санитизированный HTML (bluemonday, allowlist: p, br, b/strong, i/em, u, h2,
	// h3, ul/ol/li). Санитизация происходит на записи, а не на
	// чтении: иначе апгрейд санитайзера молча меняет
	// отображение старых записей. На выдаче фильтр
	// применяется повторно — как страховка.
	AboutHtml OptNilString `json:"aboutHtml"`
	// До трёх на любом этапе; ровно три требуется для
	// публикации. Ограничение живёт в use-case, а не в БД — deferred
	// constraint на «ровно 3» усложняет каждую промежуточную
	// запись.
	Tags     []ProfileTag `json:"tags"`
	Contacts OptContacts  `json:"contacts"`
	// Выносить ли адрес и телефоны компании на страницу
	// (пункт ТЗ про доп. информацию).
	ShowCompanyContacts bool `json:"showCompanyContacts"`
	// PNG-карточка. Имя файла — хэш от (данные профиля + версия
	// рендерера), поэтому URL меняется сам при любой правке, а
	// правка макета в коде разом обесценивает все старые
	// картинки без ручной чистки.
	CardImageUrl OptNilURI `json:"cardImageUrl"`
	CreatedAt    Timestamp `json:"createdAt"`
	UpdatedAt    Timestamp `json:"updatedAt"`
}

